    /**
     * Operation metadata by id, or null if unknown. Typed accessor so callers
     * (and PHPStan) see a plain array rather than the huge const literal.
     *
     * @return array<string,mixed>|null
     */
    public static function get(string $operationId): array|null
    {
        /** @var array<string,array<string,mixed>> $operations */
        $operations = self::OPERATIONS;
        return $operations[$operationId] ?? null;
    }

    /** @return array<string,array<string,string>> */
    public static function groups(): array
    {
        /** @var array<string,array<string,string>> $groups */
        $groups = self::GROUPS;
        return $groups;
    }

    /**
     * All operation metadata by id. Typed accessor so callers (and PHPStan)
     * see a plain array rather than the huge const literal.
     *
     * @return array<string,array<string,mixed>>
     */
    public static function all(): array
    {
        /** @var array<string,array<string,mixed>> $operations */
        $operations = self::OPERATIONS;
        return $operations;
    }
}

